get_shipping_settings.code:
final response = await client.shippingSettings.getShippingSettings();
final shippingSettings = (response.map as Map)['shipping_settings'] as Map;
print(shippingSettings['default_shipping_profile']);
print(shippingSettings['enable_shipping_class']);

patch_shipping_settings.code:
final response = await client.shippingSettings.patchShippingSettings({
  'shipping_settings': {'enable_shipping_default_tax': true},
});
final shippingSettings = (response.map as Map)['shipping_settings'] as Map;
print(shippingSettings['enable_shipping_default_tax']);
